  async reviewSourceAuthority(userId,topicId,sourceId,input){const client=await this.pool.connect();try{await client.query('BEGIN');const source=(await client.query(`SELECT s.* FROM tool_research_sources s JOIN tool_research_topic_sources ts ON ts.source_id=s.id JOIN tool_research_topics t ON t.id=ts.topic_id WHERE t.user_id=$1 AND t.id=$2 AND s.id=$3 FOR UPDATE OF s`,[userId,topicId,sourceId])).rows[0];if(!source){await client.query('ROLLBACK');return null;}const review=(await client.query(`INSERT INTO tool_research_source_authority_reviews(id,topic_id,source_id,reviewer_user_id,previous_tier,decided_tier,rationale,basis) VALUES($1,$2,$3,$4,$5,$6,$7,'manual-review') RETURNING *`,[input.id,topicId,sourceId,userId,source.authority_tier,input.decidedTier,input.rationale])).rows[0];await client.query('UPDATE tool_research_sources SET authority_tier=$2,updated_at=now() WHERE id=$1',[sourceId,input.decidedTier]);await client.query('COMMIT');return viewAuthorityReview(review);}catch(error){try{await client.query('ROLLBACK');}catch{}throw error;}finally{client.release();}}
  async listSourceRelationships(userId,topicId,{limit=100}={}){return(await this.pool.query(`SELECT latest.*,left_source.canonical_url AS left_source_url,left_source.source_type AS left_source_type,left_source.publisher AS left_source_publisher,right_source.canonical_url AS right_source_url,right_source.source_type AS right_source_type,right_source.publisher AS right_source_publisher FROM (SELECT DISTINCT ON (review.left_source_id,review.right_source_id) review.* FROM tool_research_source_relationship_reviews review JOIN tool_research_topics topic ON topic.id=review.topic_id WHERE topic.user_id=$1 AND review.topic_id=$2 ORDER BY review.left_source_id,review.right_source_id,review.revision DESC) latest JOIN tool_research_sources left_source ON left_source.id=latest.left_source_id JOIN tool_research_sources right_source ON right_source.id=latest.right_source_id ORDER BY latest.created_at DESC,latest.id DESC LIMIT $3`,[userId,topicId,limit])).rows.map(viewSourceRelationship);}
  async reviewSourceRelationship(userId,topicId,{id:reviewId,leftSourceId,rightSourceId,relationship,rationale}){const [leftId,rightId]=[leftSourceId,rightSourceId].sort();const client=await this.pool.connect();try{await client.query('BEGIN');if(!(await client.query('SELECT 1 FROM tool_research_topics WHERE user_id=$1 AND id=$2 FOR UPDATE',[userId,topicId])).rowCount){await client.query('ROLLBACK');return{status:'missing_topic'};}const linked=(await client.query('SELECT source_id FROM tool_research_topic_sources WHERE topic_id=$1 AND source_id=ANY($2::uuid[]) ORDER BY source_id',[topicId,[leftId,rightId]])).rows;if(linked.length!==2){await client.query('ROLLBACK');return{status:'missing_source'};}await client.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))',[`research-source-relationship:${topicId}:${leftId}:${rightId}`]);const revision=Number((await client.query('SELECT COALESCE(max(revision),0)+1 AS revision FROM tool_research_source_relationship_reviews WHERE topic_id=$1 AND left_source_id=$2 AND right_source_id=$3',[topicId,leftId,rightId])).rows[0].revision);const row=(await client.query(`INSERT INTO tool_research_source_relationship_reviews(id,topic_id,left_source_id,right_source_id,revision,actor_user_id,relationship,rationale) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *`,[reviewId,topicId,leftId,rightId,revision,userId,relationship,rationale])).rows[0],sources=(await client.query('SELECT id,canonical_url,source_type,publisher FROM tool_research_sources WHERE id=ANY($1::uuid[])',[[leftId,rightId]])).rows,byId=new Map(sources.map(source=>[source.id,source]));await client.query('COMMIT');return{status:'reviewed',review:viewSourceRelationship({...row,left_source_url:byId.get(leftId)?.canonical_url,left_source_type:byId.get(leftId)?.source_type,left_source_publisher:byId.get(leftId)?.publisher,right_source_url:byId.get(rightId)?.canonical_url,right_source_type:byId.get(rightId)?.source_type,right_source_publisher:byId.get(rightId)?.publisher})};}catch(error){try{await client.query('ROLLBACK');}catch{}throw error;}finally{client.release();}}
   async ensureRunSourceAdmissions(runId){const client=await this.pool.connect();try{await client.query('BEGIN');const context=(await client.query(`SELECT r.id,r.topic_id,r.source_admissions_frozen_at,c.contract_json FROM tool_research_runs r JOIN tool_research_topic_contracts c ON c.topic_id=r.topic_id AND c.version=r.contract_version WHERE r.id=$1 AND r.status='observing' FOR UPDATE OF r`,[runId])).rows[0];if(!context){await client.query('ROLLBACK');return{context:null,rows:[]};}if(!context.source_admissions_frozen_at){const sources=(await client.query(`SELECT s.*,ts.pinned,ts.added_by,ts.added_reason,ts.watch_id FROM tool_research_sources s JOIN tool_research_topic_sources ts ON ts.source_id=s.id WHERE ts.topic_id=$1 AND ts.status='tracked' ORDER BY ts.pinned DESC,s.last_seen_at,s.id LIMIT 500`,[context.topic_id])).rows;for(const source of sources)await recordRunSourceAdmission(client,{runId,source,contract:context.contract_json});await client.query('UPDATE tool_research_runs SET source_admissions_frozen_at=now() WHERE id=$1 AND source_admissions_frozen_at IS NULL',[runId]);}const rows=(await client.query(`SELECT s.*,rs.decision,rs.reason,rs.minimum_authority_tier,rs.authority_tier AS admitted_authority_tier,rs.created_at AS admitted_at,ts.pinned,ts.added_by,ts.added_reason,ts.watch_id FROM tool_research_run_sources rs JOIN tool_research_sources s ON s.id=rs.source_id JOIN tool_research_topic_sources ts ON ts.topic_id=$2 AND ts.source_id=s.id WHERE rs.run_id=$1 ORDER BY ts.pinned DESC,s.last_seen_at,s.id`,[runId,context.topic_id])).rows;await client.query('COMMIT');return{context:{...context,source_admissions_frozen_at:context.source_admissions_frozen_at||new Date()},rows};}catch(error){try{await client.query('ROLLBACK');}catch{}throw error;}finally{client.release();}}
