  async getProviderCircuitStatus(){if(!Object.keys(this.providerPrices).length)return[];return (await this.pool.query(`SELECT provider,state,consecutive_failures,retry_after,probe_until,last_error_code,updated_at FROM tool_research_provider_circuits WHERE provider=ANY($1::text[]) ORDER BY provider`,[Object.keys(this.providerPrices)])).rows.map(row=>({provider:row.provider,state:row.state,consecutiveFailures:Number(row.consecutive_failures),retryAt:iso(row.retry_after),probeUntil:iso(row.probe_until),lastErrorCode:row.last_error_code||null,updatedAt:iso(row.updated_at)}));}
